<?php
$search=scalar_value($_GET,'search');$status=scalar_value($_GET,'status');$where=[];$params=[];
if($search!==''){$where[]='(o.reference LIKE ? OR u.email LIKE ? OR u.name LIKE ?)';$params=array_fill(0,3,'%'.$search.'%');}
if(in_array($status,['Confirmed','Processing','Shipped','Completed','Cancelled'],true)){$where[]='o.status=?';$params[]=$status;}
$orders=all('SELECT o.*,u.email FROM orders o JOIN users u ON u.id=o.user_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY o.id DESC',$params);
$detail=isset($_GET['view'])?one('SELECT o.*,u.email,a.name updated_by FROM orders o JOIN users u ON u.id=o.user_id LEFT JOIN users a ON a.id=o.last_status_updated_by_admin_id WHERE o.id=?',[(int)$_GET['view']]):null;
?>
<form method="get" class="inline-form"><input type="hidden" name="page" value="admin"><input type="hidden" name="section" value="orders"><label>Reference, customer name or email<input name="search" value="<?=e($search)?>" maxlength="100"></label><label>Status<select name="status"><option value="">All</option><?php foreach(['Confirmed','Processing','Shipped','Completed','Cancelled'] as $s):?><option <?=$s===$status?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></label><button class="btn btn-outline">Search</button><a href="<?=e(url('admin',['section'=>'orders']))?>">Clear</a></form>
<section class="admin-card"><h2>Order register</h2><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php foreach($orders as $o):?><tr><td><a href="<?=e(url('admin',['section'=>'orders','view'=>$o['id']]))?>"><?=e($o['reference'])?></a><small><?=e($o['created_at'])?></small></td><td><?=e($o['email'])?></td><td><?=money($o['total'])?></td><td><?=e($o['status'])?></td><td>
<?php $next=['Confirmed'=>'Processing','Processing'=>'Shipped','Shipped'=>'Completed'];if(isset($next[$o['status']])):?><form method="post"><?php admin_hidden('admin_order_status','orders',(int)$o['id']);?><input type="hidden" name="status" value="<?=e($next[$o['status']])?>"><button class="text-button">Mark <?=e($next[$o['status']])?></button></form><?php endif;?>
<?php if(in_array($o['status'],['Confirmed','Processing'],true)):?><form method="post" data-confirm="Cancel this order and restore stock once?"><?php admin_hidden('cancel_order','orders',(int)$o['id']);?><button class="text-button danger">Cancel order</button></form><?php endif;?>
<?php if($o['status']==='Cancelled')delete_form('admin_order_delete','orders',(int)$o['id'],'Delete cancelled order');?></td></tr><?php endforeach;?>
<?php if(!$orders):?><tr><td colspan="5">No matching orders.</td></tr><?php endif;?></tbody></table></div></section>
<?php if($detail):?><section class="admin-card"><h2><?=e($detail['reference'])?></h2><p><?=e($detail['recipient'].' · '.$detail['phone'].' · '.$detail['email'])?><br><?=e($detail['address'])?></p>
<?php foreach(all('SELECT * FROM order_items WHERE order_id=?',[$detail['id']]) as $item):?><p><?=e($item['name'].' / '.$item['color'].' / '.$item['size'])?> × <?=$item['quantity']?> — <?=money((float)$item['unit_price']*$item['quantity'])?></p><?php endforeach;?>
<p>Subtotal: <?=money($detail['subtotal'])?> · Discount: <?=money($detail['discount_amount'])?> <?=e($detail['promo_code_used']??'')?> · Shipping: <?=money($detail['shipping'])?></p><strong>Total: <?=money($detail['total'])?></strong>
<h3>Payment record</h3><?php $payment=one('SELECT * FROM payments WHERE order_id=?',[$detail['id']]);if($payment):?><p><?=e($payment['payment_method'].' · '.$payment['payment_status'].' · '.$payment['payment_reference'])?><br><?=money($payment['amount'])?> · <?=e($payment['paid_at'])?></p><?php endif;?>
<h3>Status history</h3><?php foreach(all('SELECT h.*,u.name actor FROM order_status_history h LEFT JOIN users u ON u.id=h.actor_user_id WHERE h.order_id=? ORDER BY h.id',[$detail['id']]) as $h):?><p><?=e(($h['from_status']??'New').' → '.$h['to_status'])?> · <?=e($h['actor']??'System')?> · <?=e($h['changed_at'])?></p><?php endforeach;?><p>Last administrator: <?=e($detail['updated_by']??'Not updated by an administrator')?></p></section><?php endif;?>
